def max_area(height):
    n = len(height)
    best = 0
    for i in range(n):
        for j in range(i + 1, n):
            area = (j - i) * min(height[i], height[j])
            if area > best:
                best = area
    return best


def main():
    height = list(map(int, input().split()))
    print(max_area(height))


if __name__ == "__main__":
    main()

