    best = 0
    while l < r:
        hl, hr = height[l], height[r]
        best = max(best, (r - l) * min(hl, hr))
        if hl < hr:
            l += 1
            while l < r and height[l] <= hl:
                l += 1
        else:
            r -= 1
            while l < r and height[r] <= hr:
                r -= 1
    return best


